    out = [row[:] for row in grid]

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue

            # A 2 marks the center of a 3x3 patch. Color only cells belonging
            # to a 3-region, while allowing the patch to extend into nearby
            # background where the region's edge is interrupted.
            for y in range(max(0, r - 1), min(h, r + 2)):
                for x in range(max(0, c - 1), min(w, c + 2)):
                    if grid[y][x] == 3:
                        out[y][x] = 1

    # Adjacent markers in a marked patch are replaced too.
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and any(
                0 <= r + dr < h and 0 <= c + dc < w and grid[r + dr][c + dc] == 3
                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                if dr or dc
            ):
                out[r][c] = 1
    return out
