                for dr in (-1, 0, 1) for dc in (-1, 0, 1)
            )
            if not near_three:
                continue

            for y in range(max(0, r - 1), min(h, r + 2)):
                for x in range(max(0, c - 1), min(w, c + 2)):
                    if grid[y][x] != 2:
                        out[y][x] = 1

            # Markers outside the 3-region are part of the patch and become 1.
            if not any(grid[r + dr][c + dc] == 3
                       for dr in (-1, 0, 1) for dc in (-1, 0, 1)
                       if 0 <= r + dr < h and 0 <= c + dc < w):
                out[r][c] = 1
    return out
